const form=document.getElementById("vatForm"),result=document.getElementById("result");form&&form.addEventListener("submit",n=>{n.preventDefault();const t=parseFloat(document.getElementById("amount").value)||0,i=document.getElementById("target").value,a=parseFloat(document.getElementById("rate").value);if(t<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите сумму больше нуля.</p>';return}let s=t,e=0,l=t;i==="add"?(e=t*a/100,s=t,l=t+e):(e=t*a/(100+a),s=t-e,l=t),result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>База (без НДС)</span><span class="val">${fmt(s)} ₽</span></div>
        <div class="item total"><span>НДС ${fmt(a)}%</span><span class="val">${fmt(e)} ₽</span></div>
        <div class="item"><span>Сумма с НДС</span><span class="val">${fmt(l)} ₽</span></div>
      </div>
      <p class="hint" style="margin-top:14px">${i==="add"?"НДС начислен сверху.":"НДС выделен из суммы."}</p>
    `});function fmt(n){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(n)}
